import uuid

from fastapi import APIRouter, Depends, HTTPException, Query, status
from sqlalchemy.orm import Session

from src.backend.core.deps import get_current_user, require_role
from src.backend.core.roles import Role
from src.backend.db.session import get_db
from src.backend.models.user import User
from src.backend.schemas.token import (
    TokenCreate,
    TokenListResponse,
    TokenRead,
    TokenUpdate,
)
from src.backend.services.token_service import (
    TokenServiceError,
    create_token,
    delete_token,
    get_token,
    list_tokens,
    transition_token_status,
    update_token,
)

router = APIRouter(prefix="/api", tags=["tokens"])


@router.post("/tokens", status_code=status.HTTP_201_CREATED)
def create_token_endpoint(
    token_data: TokenCreate,
    current_user: User = Depends(get_current_user),
    db: Session = Depends(get_db),
):
    try:
        token = create_token(
            db=db,
            token_date=token_data.token_date,
            agreement_id=token_data.agreement_id,
            token_type=token_data.token_type,
            description=token_data.description,
            token_status=token_data.token_status,
            tokens_used=token_data.tokens_used,
            swa_team_lead=token_data.swa_team_lead,
            project_owner=token_data.project_owner,
            client_employee_name=token_data.client_employee_name,
            client_employee_email=token_data.client_employee_email,
            notes=token_data.notes,
            created_by=current_user.id,
        )
        return TokenRead.model_validate(token)
    except Exception as e:
        raise HTTPException(status_code=400, detail=str(e)) from e


@router.get("/tokens/{token_id}", response_model=TokenRead)
def get_token_endpoint(
    token_id: uuid.UUID,
    _: User = Depends(get_current_user),
    db: Session = Depends(get_db),
):
    token = get_token(db, token_id)
    if not token:
        raise HTTPException(status_code=404, detail="Token not found")
    return TokenRead.model_validate(token)


@router.get("/tokens", response_model=TokenListResponse)
def list_tokens_endpoint(
    agreement_id: uuid.UUID | None = Query(None, alias="agreement_id"),
    token_status: str | None = Query(None, alias="token_status"),
    page: int = Query(default=1, ge=1),
    page_size: int = Query(default=20, ge=1, le=100),
    _: User = Depends(get_current_user),
    db: Session = Depends(get_db),
):
    items, total = list_tokens(
        db,
        agreement_id=agreement_id,
        token_status=token_status,
        page=page,
        page_size=page_size,
    )
    return TokenListResponse(
        items=[TokenRead.model_validate(item) for item in items],
        total=total,
        page=page,
        page_size=page_size,
    )


@router.patch("/tokens/{token_id}", response_model=TokenRead)
def update_token_endpoint(
    token_id: uuid.UUID,
    update_data: TokenUpdate,
    current_user: User = Depends(get_current_user),
    db: Session = Depends(get_db),
):
    try:
        token = update_token(
            db=db,
            token_id=token_id,
            update_data=update_data.model_dump(exclude_unset=True),
            updated_by=current_user.id,
        )
        if not token:
            raise HTTPException(status_code=404, detail="Token not found")
        return TokenRead.model_validate(token)
    except Exception as e:
        raise HTTPException(status_code=400, detail=str(e)) from e


@router.delete("/tokens/{token_id}", status_code=status.HTTP_204_NO_CONTENT)
def delete_token_endpoint(
    token_id: uuid.UUID,
    current_user: User = Depends(require_role(Role.ADMIN)),
    db: Session = Depends(get_db),
):
    try:
        success = delete_token(db, token_id, deleted_by=current_user.id)
        if not success:
            raise HTTPException(status_code=404, detail="Token not found")
    except TokenServiceError as e:
        raise HTTPException(status_code=400, detail=str(e)) from e


@router.post("/tokens/{token_id}/transition-status", response_model=TokenRead)
def transition_token_status_endpoint(
    token_id: uuid.UUID,
    new_status: str,
    current_user: User = Depends(get_current_user),
    db: Session = Depends(get_db),
):
    try:
        token = transition_token_status(
            db=db,
            token_id=token_id,
            new_status=new_status,
            transitioned_by=current_user.id,
        )
        if not token:
            raise HTTPException(status_code=404, detail="Token not found")
        return TokenRead.model_validate(token)
    except TokenServiceError as e:
        raise HTTPException(status_code=400, detail=str(e)) from e


@router.get("/agreements/{agreement_id}/tokens", response_model=TokenListResponse)
def list_tokens_by_agreement(
    agreement_id: uuid.UUID,
    _: User = Depends(get_current_user),
    db: Session = Depends(get_db),
):
    from src.backend.services.token_service import get_tokens_by_agreement

    tokens = get_tokens_by_agreement(db, agreement_id)
    return TokenListResponse(
        items=[TokenRead.model_validate(token) for token in tokens],
        total=len(tokens),
        page=1,
        page_size=len(tokens),
    )

